import{_ as a}from"./chunks/plus.s75sSGIW.js";import{_ as r,c as d,o as e,a7 as o}from"./chunks/framework.DLVsJyUe.js";const s="/ruidu-docs/icons/minus.svg",i="/ruidu-docs/icons/maximize.svg",h="/ruidu-docs/images/orbitcontrol/user-guide/map-toolbar-map-tools.png",g=JSON.parse('{"title":"地图操作","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/map.md","filePath":"orbitcontrol/user-guide/map.md"}'),l={name:"orbitcontrol/user-guide/map.md"};function n(c,t,m,p,u,b){return e(),d("div",null,t[0]||(t[0]=[o('<h1 id="地图操作" tabindex="-1">地图操作 <a class="header-anchor" href="#地图操作" aria-label="Permalink to &quot;地图操作&quot;">​</a></h1><p>平台的大部分页面（设备控制、任务、标注、路网等）以地图为工作底板。本章说明地图的通用概念与操作，各业务页面不再重复。</p><h2 id="世界地图与本地地图" tabindex="-1">世界地图与本地地图 <a class="header-anchor" href="#世界地图与本地地图" aria-label="Permalink to &quot;世界地图与本地地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>地图</th><th>说明</th></tr></thead><tbody><tr><td><strong>世界地图</strong></td><td>在线卫星/街道底图，按经纬度展示全局位置</td></tr><tr><td><strong>本地地图</strong></td><td>设备建图产出的场地内部地图</td></tr></tbody></table><p>在哪种地图上作业没有强制限制，取决于设备所处的环境：未建图或室外场景在世界地图上作业，场地内完成建图后可切换到本地地图。</p><p>点击地图左上角的「选择地图」按钮可切换当前显示的地图：列表展示站点下可用的地图，带地球图标的是世界地图类地图，其余为本地地图。</p><p>本地地图由设备建图产出，建图与管理见 <a href="./maps.html">地图管理</a>。</p><h2 id="各功能的地图使用" tabindex="-1">各功能的地图使用 <a class="header-anchor" href="#各功能的地图使用" aria-label="Permalink to &quot;各功能的地图使用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>地图使用</th><th>详见</th></tr></thead><tbody><tr><td>设备控制</td><td>自动加载设备所属站点的地图，站点没有地图时显示世界地图</td><td><a href="./live-control.html">设备控制</a></td></tr><tr><td>任务</td><td>任务归属站点，可在站点的多张地图上分别绘制航点（跨地图任务）</td><td><a href="./missions.html">任务</a></td></tr><tr><td>标注</td><td>标注归属地图，每张地图维护自己的标注</td><td><a href="./annotations.html">标注</a></td></tr><tr><td>路网</td><td>路网归属地图，每张地图维护自己的路网</td><td><a href="./route-graph.html">路网</a></td></tr></tbody></table><h2 id="基础操作" tabindex="-1">基础操作 <a class="header-anchor" href="#基础操作" aria-label="Permalink to &quot;基础操作&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>方式</th></tr></thead><tbody><tr><td>缩放</td><td>滚轮，或右侧控件 <img src="'+a+'" alt=""> 放大、<img src="'+s+'" alt=""> 缩小</td></tr><tr><td>平移</td><td>按住鼠标左键拖动</td></tr><tr><td>重置视图</td><td>右侧控件 <img src="'+i+'" alt="">，回到当前地图的完整范围</td></tr></tbody></table><p><img src="'+h+'" alt=""></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>在本地地图上，缩放经过优化为平滑的分数级缩放，可以精细地观察地图细节。</p></div>',13)]))}const x=r(l,[["render",n]]);export{g as __pageData,x as default};
